   273→    <script>
   274→        function togglePassword() {
   275→            const passwordInput = document.getElementById('password');
   276→            const eyeIcon = document.getElementById('eyeIcon');
   277→            const eyeOffIcon = document.getElementById('eyeOffIcon');
   278→            
   279→            if (passwordInput.type === 'password') {
   280→                passwordInput.type = 'text';
   281→                eyeIcon.style.display = 'none';
   282→                eyeOffIcon.style.display = 'block';
   283→            } else {
   284→                passwordInput.type = 'password';
   285→                eyeIcon.style.display = 'block';
   286→                eyeOffIcon.style.display = 'none';
   287→            }
   288→            passwordInput.focus();
   289→        }
   290→
   291→        function validateEmail(email) {
   292→            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
   293→        }
   294→
   295→        document.getElementById('loginForm').addEventListener('submit', function(e) {
   296→            e.preventDefault();
   297→            
   298→            const emailInput = document.getElementById('email');
   299→            const passwordInput = document.getElementById('password');
   300→            const email = emailInput.value.trim();
   301→            const password = passwordInput.value;
   302→            const emailError = document.getElementById('emailError');
   303→            const passwordError = document.getElementById('passwordError');
   304→            let isValid = true;
   305→
   306→            // Reset styles
   307→            emailInput.classList.remove('input-error');
   308→            passwordInput.classList.remove('input-error');
   309→
   310→            if (!email || !validateEmail(email)) {
   311→                emailError.classList.remove('hidden');
   312→                emailInput.classList.add('input-error');
   313→                isValid = false;
   314→            } else {
   315→                emailError.classList.add('hidden');
   316→            }
   317→
   318→            if (!password) {
   319→                passwordError.classList.remove('hidden');
   320→                passwordInput.classList.add('input-error');
   321→                isValid = false;
   322→            } else {
   323→                passwordError.classList.add('hidden');
   324→            }
   325→
   326→            if (!isValid) return;
   327→            
   328→            const btn = document.getElementById('submitBtn');
   329→            const btnText = document.getElementById('btnText');
   330→            const btnSpinner = document.getElementById('btnSpinner');
   331→            
   332→            btn.disabled = true;
   333→            btn.setAttribute('aria-busy', 'true');
   334→            btnText.textContent = '登录中…';
   335→            btnSpinner.classList.remove('hidden');
   336→
   337→            setTimeout(() => {
   338→                btn.disabled = false;
   339→                btn.setAttribute('aria-busy', 'false');
   340→                btnText.textContent = '登录';
   341→                btnSpinner.classList.add('hidden');
   342→                alert(`登录成功！\n欢迎用户: ${email}`);
   343→            }, 1500);
   344→        });
   345→
   346→        document.getElementById('email').addEventListener('input', () => {
   347→            document.getElementById('emailError').classList.add('hidden');
   348→            document.getElementById('email').classList.remove('input-error');
   349→        });
   350→        document.getElementById('password').addEventListener('input', () => {
   351→            document.getElementById('passwordError').classList.add('hidden');
   352→            document.getElementById('password').classList.remove('input-error');
   353→        });
   354→    </script>
